package com.marinainsaurralde.plango.data;
import com.marinainsaurralde.plango.model.*;import java.text.Normalizer;import java.util.*;
public final class AgrupadorEventos {public enum Categoria{TEATRO,MUSICA,CINE,EXPOSICIONES,OTRAS}private AgrupadorEventos(){}public static List<GrupoUbicacion> agrupar(List<Evento> eventos){Map<Clave,List<Evento>>groups=new LinkedHashMap<>();if(eventos!=null)for(Evento e:eventos)if(e.hasValidCoordinates())groups.computeIfAbsent(new Clave(e.getLatitud(),e.getLongitud()),k->new ArrayList<>()).add(e);List<GrupoUbicacion>result=new ArrayList<>();groups.forEach((k,v)->result.add(new GrupoUbicacion(k.lat,k.lon,v)));return result;}public static Categoria categoria(Evento e){String raw=e==null?null:e.getTipo();if(raw==null)return Categoria.OTRAS;String s=Normalizer.normalize(raw,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT);if(s.contains("teatro")||s.contains("performance"))return Categoria.TEATRO;if(s.contains("musica")||s.contains("concierto"))return Categoria.MUSICA;if(s.contains("cine")||s.contains("audiovisual"))return Categoria.CINE;if(s.contains("exposicion")||s.contains("museo"))return Categoria.EXPOSICIONES;return Categoria.OTRAS;}private static final class Clave{final double lat,lon;Clave(double a,double o){lat=a;lon=o;}public boolean equals(Object x){if(!(x instanceof Clave))return false;Clave k=(Clave)x;return Double.doubleToLongBits(lat)==Double.doubleToLongBits(k.lat)&&Double.doubleToLongBits(lon)==Double.doubleToLongBits(k.lon);}public int hashCode(){return Objects.hash(Double.doubleToLongBits(lat),Double.doubleToLongBits(lon));}}}
